 const pos=accessor(model,prim.attributes.POSITION),nor=accessor(model,prim.attributes.NORMAL),joints=accessor(model,prim.attributes.JOINTS_0),weights=accessor(model,prim.attributes.WEIGHTS_0),indices=accessor(model,prim.indices),ibmAcc=accessor(model,skin.inverseBindMatrices)
 const cache=new Map(),get=i=>{if(!cache.has(i))cache.set(i,accessor(model,i));return cache.get(i)}
